INSERT INTO public.system_changelog (version, title, description, changes, category)
SELECT '3.64.7', 'Persistência do aviso de perfil', 'O aviso acompanha cada abertura de página até o perfil estar completo.', to_jsonb(ARRAY['O modal reaparece a cada navegação, retorno à mesma página e recarregamento enquanto faltarem campos.', 'Fechar ou escolher Lembrar mais tarde libera somente o instante atual, sem salvar dispensa por página ou sessão.', 'Completar os 12 campos obrigatórios encerra o aviso; remover informação obrigatória o reativa. Pitch por IA permanece opcional.', 'A página de edição do perfil permanece livre do aviso automático; vídeo, perfil e guia continuam sem sobreposição.']::text[]), 'fix'
WHERE NOT EXISTS (SELECT 1 FROM public.system_changelog WHERE version = '3.64.7');